                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Live Payload Summary Banner */}
          <div className="rounded-lg border border-border bg-muted/30 p-4">
            <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3">
