                                            const matchingOption = testCaseOptions.find(
                                              (opt) => opt.label === text
                                            );
                                            field.onChange(
                                              matchingOption ? matchingOption.value : undefined
                                            );
                                          }}
                                          onBlur={() => {
                                            const matchingOption = testCaseOptions.find(
                                              (opt) => opt.label === testCaseInputText
