                                                <SelectItem key={sprint.id} value={sprint.id}>{sprint.title}</SelectItem>
                                            ))}
                                            </SelectContent>
                                        </Select>
                                        <FormMessage />
                                    </FormItem>
                                    )}
                                />
                                <FormField
                                    control={editStoryForm.control}
                                    name="releaseId"
                                    render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Release</FormLabel>
