                                        setEditParentStoryText('');
                                        field.onChange(undefined);
                                      }
                                    }}
                                  />
                                </div>
                              </FormControl>
                              <datalist id="parent-story-options-defect-edit-kanban">
                                {parentStoryOptions
                                  .filter(opt => matchSearchQuery(opt.label, editParentStoryText))
