                                  .map(opt => <option key={opt.value} value={opt.label} />)}
                              </datalist>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField
                          control={editStoryForm.control}
                          name="severity"
