                              </FormControl>
                              <datalist id="parent-story-options-edit">
                                  {parentStoryOptions
                                    .filter(opt => matchSearchQuery(opt.label, editParentStoryText))
                                    .map(opt => <option key={opt.value} value={opt.label} />)}
                              </datalist>
                              <FormMessage />
                              </FormItem>
