  const addUserToProject = async (employee: Employee): Promise<boolean> => {
    if (!db || !projectId) return false;

    // Check if employee is already in the project
    if (employees.some(e => e.id === employee.id)) {
      return false;
    }

    try {
      const normalizeDateStr = (d: any): string | null => {
        if (!d) return null;
        try {
          if (typeof d === 'string') return d.slice(0, 10);
          if (d instanceof Date) return d.toISOString().slice(0, 10);
          if (d?.toDate) return d.toDate().toISOString().slice(0, 10);
          return new Date(d).toISOString().slice(0, 10);
        } catch {
          return null;
        }
      };

      const onDateStr = normalizeDateStr(employee.onboardingDate);
      const offDateStr = normalizeDateStr(employee.offloadingDate);
      const projStartStr = normalizeDateStr(project?.startDate);
      const projEndStr = normalizeDateStr(project?.endDate);

      if (onDateStr && offDateStr && offDateStr < onDateStr) {
        console.error("Firebase Error: Offboarding date cannot be earlier than onboarding date.");
        return false;
      }
      if (projStartStr && onDateStr && onDateStr < projStartStr) {
        console.error("Firebase Error: Onboarding date cannot be earlier than project start date.");
        return false;
      }
      if (projEndStr && offDateStr && offDateStr > projEndStr) {
        console.error("Firebase Error: Offboarding date cannot be later than project end date.");
        return false;
      }

      // Add the employee document to the project's subcollection
      // We use setDoc with the global employee ID to keep them in sync
      await setDoc(doc(db, 'projects', projectId, 'employees', employee.id), sanitizeForFirestore(employee));
      return true;
    } catch (e: any) {
      console.error("Firebase Error: Failed to add employee to project.", { code: e.code, message: e.message, fullError: e });
      return false;
    }
  };

