    updateTestCycle,
    deleteTestCycle,
    addTestCasesToCycle,
    updateTestCycleTestCase,
    removeTestCasesFromCycle,
    subscribeToTestCycleTestCases,
    addTestPlan,
    updateTestPlan,
    deleteTestPlan,
    addTestCasesToPlan,
    updateTestPlanTestCase,
    removeTestCasesFromPlan,
    subscribeToTestPlanTestCases,

    addRisk,
    updateRisk,
    deleteRisk,
    autoGenerateRisks,
    addAssumption,
    updateAssumption,
    deleteAssumption,
    autoGenerateAssumptions,
    addIssue,
    updateIssue,
    deleteIssue,

    addDependency,
    updateDependency,
    deleteDependency,
    autoGenerateDependencies,
    addReleaseOrMilestone,
    updateReleaseOrMilestone,
    deleteReleaseOrMilestone,
    addKanbanColumn,
    updateKanbanColumn,
    deleteKanbanColumn,
    updateKanbanColumnOrder,
    updateProjectSettings,
    setWeeklyOffDays,
    updateSprintSettings,
    updateEffortSettings,
    addHoliday,
    updateHoliday,
    deleteHoliday,
    addImpactedSystem,
    updateImpactedSystem,
    deleteImpactedSystem,
    replaceImpactedSystems,
    addInitialImpactedSystem,
    updateInitialImpactedSystem,
    deleteInitialImpactedSystem,
    replaceInitialImpactedSystems,
    addInitialHorizontal,
    updateInitialHorizontal,
    deleteInitialHorizontal,
    replaceInitialHorizontals,
    confirmInitialEstimation,
    addHorizontal,
    updateHorizontal,
    deleteHorizontal,
    replaceHorizontals,
    addEnvironment,
    updateEnvironment,
    deleteEnvironment,
    updateEnvironmentOrder,
    saveWorklog,

    addDocument,
    updateDocument,
    deleteDocument,
    addPaymentMilestone,
    updatePaymentMilestone,
    deletePaymentMilestone,
    addCodeRepository,
    updateCodeRepository,
    deleteCodeRepository,
    addFixedCost,
    updateFixedCost,
    deleteFixedCost,
    restoreItem,
    permanentlyDeleteItem,
  };

  if (isLoading) {
    return (
      <div className="flex h-screen w-full items-center justify-center bg-background">
        <div className="flex flex-col items-center gap-4">
          <div className="h-12 w-12 animate-spin rounded-full border-4 border-primary border-t-transparent" />
          <p className="text-muted-foreground">Loading project data...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex h-screen w-full items-center justify-center bg-background p-8">
        <div className="max-w-2xl rounded-lg border border-destructive bg-destructive/10 p-6 text-center text-destructive">
          <h2 className="text-2xl font-bold">Database Connection Error</h2>
          <p className="mt-2 text-destructive/80">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <ProjectContext.Provider value={value}>
      {children}
    </ProjectContext.Provider>
  );
}

