    if (!db || !projectId) return false;

    const getRandomItem = <T,>(arr: T[]): T | undefined => arr.length > 0 ? arr[Math.floor(Math.random() * arr.length)] : undefined;
    const projectReleases = releasesAndMilestones.filter(r => r.itemType === 'Release');

    try {
