    const sortedEnvironments = [...environments].sort((a, b) => a.order - b.order);
    const movedEnvironments = arrayMove(sortedEnvironments, oldIndex, newIndex);
    
    setEnvironments(movedEnvironments.map((env, index) => ({ ...env, order: index })));

